function domainReading(domain, evidence) {
    const relevant = evidence.filter(item => item.domain === domain);
    const score = relevant.reduce((total, item) => {
        if (item.polarity === 'opportunity')
            return total + item.weight;
        if (item.polarity === 'risk')
            return total - item.weight;
        return total;
    }, 0);
    const opportunities = relevant.filter(item => item.polarity === 'opportunity' || item.polarity === 'mixed').map(item => item.statement).slice(0, 4);
    const risks = relevant.filter(item => item.polarity === 'risk' || item.polarity === 'mixed').map(item => item.statement).slice(0, 4);
    const hasOpportunity = relevant.some(item => item.polarity === 'opportunity');
    const hasRisk = relevant.some(item => item.polarity === 'risk');
    const summary = !relevant.length
        ? '这部分的盘面线索还不够，先别急着下结论。'
        : hasOpportunity && hasRisk
            ? '这里好的一面和费力的地方都很明显。能不能发挥出来，关键看你是否把优势变成稳定习惯，同时避开那些代价较高的触发点。'
            : score > 1
                ? '有利的线索更多一些，大概率比较容易发挥；不过具体走到哪一步，仍要看阶段和现实选择。'
                : score < -1
                    ? '压力点比较集中，提前留余地会更合适。这只是说这个议题容易被触发，不代表坏事一定发生。'
                    : '盘里几股力量互相牵制，很难一句话说成好或坏。更适合结合你现在所处的阶段来看。';
    return {
        domain, score, confidence: confidenceFromCount(relevant.length), summary,
        opportunities, risks, evidenceIds: relevant.map(item => item.id),
    };
}
